        self.food_to_cuisine = {}
        self.food_to_rating = {}
        self.cuisine_foods = {}
        for food, cuisine, rating in zip(foods, cuisines, ratings):
            self.food_to_cuisine[food] = cuisine
            self.food_to_rating[food] = rating
            self.cuisine_foods.setdefault(cuisine, set()).add(food)

    def change_rating(self, food, new_rating):
        self.food_to_rating[food] = new_rating

    def highest_rated(self, cuisine):
        best_food = None
        best_rating = -1
        for food in self.cuisine_foods[cuisine]:
            rating = self.food_to_rating[food]
            if rating > best_rating or (rating == best_rating and food < best_food):
                best_rating = rating
                best_food = food
        return best_food


