        self.food_to_rating = {}
        self.cuisine_heap = {}
        for food, cuisine, rating in zip(foods, cuisines, ratings):
            self.food_to_cuisine[food] = cuisine
            self.food_to_rating[food] = rating
            self.cuisine_heap.setdefault(cuisine, [])
            heapq.heappush(self.cuisine_heap[cuisine], (-rating, food))

    def change_rating(self, food, new_rating):
        self.food_to_rating[food] = new_rating
        cuisine = self.food_to_cuisine[food]
        heapq.heappush(self.cuisine_heap[cuisine], (-new_rating, food))

    def highest_rated(self, cuisine):
        heap = self.cuisine_heap[cuisine]
