import java.util.*;

public class Main {
    static class FoodRatings {
        Map<String, String> foodToCuisine = new HashMap<>();
        Map<String, Integer> foodToRating = new HashMap<>();
        Map<String, PriorityQueue<AbstractMap.SimpleEntry<Integer, String>>> cuisineHeap = new HashMap<>();

        FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
            for (int i = 0; i < foods.length; i++) {
                foodToCuisine.put(foods[i], cuisines[i]);
                foodToRating.put(foods[i], ratings[i]);
                cuisineHeap.computeIfAbsent(cuisines[i], k -> makeHeap())
                    .add(new AbstractMap.SimpleEntry<>(ratings[i], foods[i]));
            }
        }

        PriorityQueue<AbstractMap.SimpleEntry<Integer, String>> makeHeap() {
            return new PriorityQueue<>((a, b) -> {
                if (!a.getKey().equals(b.getKey())) return b.getKey() - a.getKey();
                return a.getValue().compareTo(b.getValue());
            });
        }

        void changeRating(String food, int newRating) {
            foodToRating.put(food, newRating);
            cuisineHeap.get(foodToCuisine.get(food)).add(new AbstractMap.SimpleEntry<>(newRating, food));
        }

        String highestRated(String cuisine) {
            PriorityQueue<AbstractMap.SimpleEntry<Integer, String>> heap = cuisineHeap.get(cuisine);
            while (!foodToRating.get(heap.peek().getValue()).equals(heap.peek().getKey())) {
                heap.poll();
            }
            return heap.peek().getValue();
        }
    }

    public static void main(String[] args) {
        FoodRatings fr = new FoodRatings(
            new String[]{"kimchi", "miso", "sushi", "moussaka", "ramen", "bulgogi"},
            new String[]{"korean", "japanese", "japanese", "greek", "japanese", "korean"},
            new int[]{9, 12, 8, 15, 14, 7}
        );
        System.out.println(fr.highestRated("korean"));
        System.out.println(fr.highestRated("japanese"));
        fr.changeRating("sushi", 16);
        System.out.println(fr.highestRated("japanese"));
    }
}

