#include <bits/stdc++.h>
using namespace std;

class FoodRatings {
public:
    using Entry = pair<int, string>;
    unordered_map<string, string> foodToCuisine;
    unordered_map<string, int> foodToRating;
    unordered_map<string, priority_queue<Entry, vector<Entry>, greater<Entry>>> cuisineHeap;

    FoodRatings(vector<string>& foods, vector<string>& cuisines, vector<int>& ratings) {
        for (int i = 0; i < (int)foods.size(); i++) {
            foodToCuisine[foods[i]] = cuisines[i];
            foodToRating[foods[i]] = ratings[i];
            cuisineHeap[cuisines[i]].push({-ratings[i], foods[i]});
        }
    }

    void changeRating(string food, int newRating) {
        foodToRating[food] = newRating;
        cuisineHeap[foodToCuisine[food]].push({-newRating, food});
    }

    string highestRated(string cuisine) {
        auto& heap = cuisineHeap[cuisine];
        while (true) {
            auto [negRating, food] = heap.top();
            if (foodToRating[food] == -negRating) return food;
            heap.pop();
        }
    }
};

int main() {
    vector<string> foods = {"kimchi", "miso", "sushi", "moussaka", "ramen", "bulgogi"};
    vector<string> cuisines = {"korean", "japanese", "japanese", "greek", "japanese", "korean"};
    vector<int> ratings = {9, 12, 8, 15, 14, 7};
    FoodRatings fr(foods, cuisines, ratings);
    cout << fr.highestRated("korean") << endl;
    cout << fr.highestRated("japanese") << endl;
    fr.changeRating("sushi", 16);
    cout << fr.highestRated("japanese") << endl;
    return 0;
}
